=System: Social media strategist.

Summarize for social (max 250 words):
URL: {{ $json.websiteUrl }}
Prompt: {{ $json.userPrompt }}

Content:
{{ $json.scrapedContent }}

parameters.jsCode:
const platform = $('Normalize Input').first().json.platform;
const specs = { linkedin: { name: 'LinkedIn', max: 300 }, facebook: { name: 'Facebook', max: 200 }, instagram: { name: 'Instagram', max: 150 }, threads: { name: 'Threads', max: 100 }, medium: { name: 'Medium', max: 500 }, devto: { name: 'Dev.to', max: 400 }, youtube: { name: 'YouTube Community', max: 280, hint: 'Community tab text/image post only. Never video uploads, Shorts, or studio publishing.' }, producthunt: { name: 'Product Hunt', max: 260 } };
const spec = specs[platform] || specs.linkedin;
const base = $('Normalize Input').first().json.optimizedPrompt || $('Normalize Input').first().json.userPrompt;
const systemExtra = spec.hint ? ` ${spec.hint}` : '';
return [{ json: { platform, platformName: spec.name, systemPrompt: `Expert ${spec.name} creator.${systemExtra}`, userMessage: `${base}\n\nSummary:\n{{ summary }}\n\nOutput ONLY paste-ready post text.` } }];

const input = $('Normalize Input').first().json;
const content = $('Generate Platform Post').first().json.text || '';
const summary = $('Article Summarizer').first().json.text || '';
const platform = input.platform;
const tokens = input.platformTokens || {};
const token = tokens[platform];

let publishResult = { success: false, skipped: true };

if (input.publish && token?.accessToken && content) {
  try {
    if (platform === 'linkedin') {
      const personRes = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.linkedin.com/v2/userinfo', headers: { Authorization: `Bearer ${token.accessToken}` } });
      const author = `urn:li:person:${personRes.sub}`;
      await this.helpers.httpRequest({ method: 'POST', url: 'https://api.linkedin.com/v2/ugcPosts', headers: { Authorization: `Bearer ${token.accessToken}`, 'Content-Type': 'application/json', 'X-Restli-Protocol-Version': '2.0.0' }, body: { author, lifecycleState: 'PUBLISHED', specificContent: { 'com.linkedin.ugc.ShareContent': { shareCommentary: { text: content }, shareMediaCategory: 'NONE' } }, visibility: { 'com.linkedin.ugc.MemberNetworkVisibility': 'PUBLIC' } } });
      publishResult = { success: true, platform: 'linkedin' };
    } else if (platform === 'youtube') {
      publishResult = { success: false, error: 'YouTube Community auto-publish is coming soon (text/image posts only — not video uploads).' };
    } else {
      publishResult = { success: false, error: `Auto-publish not yet implemented for ${platform}. Content generated successfully.` };
    }
  } catch (e) {
    publishResult = { success: false, error: e.message };
  }
} else if (input.publish && !token) {
  publishResult = { success: false, error: 'No token provided for platform' };
}

const wordCount = content.split(/\s+/).filter(Boolean).length;
return [{ json: { success: true, executionId: input.executionId, userId: input.userId, platform, content, summary, wordCount, qualityScore: Math.min(100, wordCount * 2), publishResult, generatedAt: new Date().toISOString() } }];

const input = $('Normalize Input').first().json;
const content = $('Generate Platform Post').first().json.text || '';
const summary = $('Article Summarizer').first().json.text || '';
const wordCount = content.split(/\s+/).filter(Boolean).length;
return [{ json: { success: true, executionId: input.executionId, userId: input.userId, platform: input.platform, content, summary, wordCount, qualityScore: Math.min(100, wordCount * 2), publishResult: { success: false, skipped: true }, generatedAt: new Date().toISOString() } }];
